import { createRequire } from 'node:module';
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
const repository = process.cwd();
const directory = path.dirname(new URL(import.meta.url).pathname);
const require = createRequire(path.join(repository, 'package.json'));
const { build } = createRequire(require.resolve('vite'))('esbuild');
const modes = ['horizontal-enhanced', 'vertical-wide', 'vertical-compact', 'static'];
function intersections(points) {
  const found = [];
  const orientation = (a, b, c) => (b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);
  for(let left=0;left<points.length-1;left++) {
    const a=points[left], b=points[left+1];
    for(let right=left+2;right<points.length-1;right++) {
      const c=points[right], d=points[right+1];
      if(Math.max(a.x,b.x)<Math.min(c.x,d.x)||Math.max(c.x,d.x)<Math.min(a.x,b.x)||Math.max(a.y,b.y)<Math.min(c.y,d.y)||Math.max(c.y,d.y)<Math.min(a.y,b.y)) continue;
      if(orientation(a,b,c)*orientation(a,b,d)<-1e-7 && orientation(c,d,a)*orientation(c,d,b)<-1e-7) {
        const denominator=(b.x-a.x)*(d.y-c.y)-(b.y-a.y)*(d.x-c.x);
        const u=((c.x-a.x)*(d.y-c.y)-(c.y-a.y)*(d.x-c.x))/denominator;
        const v=((c.x-a.x)*(b.y-a.y)-(c.y-a.y)*(b.x-a.x))/denominator;
        found.push({left,right,a,b,c,d,point:{x:a.x+u*(b.x-a.x),y:a.y+u*(b.y-a.y)},tLeft:(left+u)/(points.length-1),tRight:(right+v)/(points.length-1)});
      }
    }
  }
  return found;
}
function diagnose(projection) {
  return Object.values(projection.branches).flatMap(branch=>{
    const lines=[...branch.model.staff.lines,{id:'center',points:Array.from({length:2049},(_,i)=>branch.path.pointAt(i/2048))}];
    return lines.flatMap(line=>intersections(line.points).map(hit=>{
      const zones=branch.zones.filter(zone=>zone.startT<=hit.tRight && zone.endT>=hit.tLeft);
      const visibleSegments=[hit.left,hit.right].map(index=>branch.model.primitives.filter(primitive=>primitive.role==='staff-line'&&primitive.kind==='polyline'&&(primitive.opacity??1)>0&&primitive.points.some((point,j)=>j<primitive.points.length-1&&point.x===line.points[index].x&&point.y===line.points[index].y&&primitive.points[j+1].x===line.points[index+1].x&&primitive.points[j+1].y===line.points[index+1].y)).map(({id,opacity})=>({id,opacity:opacity??1})));
      return {branch:branch.branch,line:line.id,staffStep:line.id.split(':').at(-1),kind:line.id==='center'?'center-path':'individual-staff-line',...hit,segmentIds:[`${line.id}/segment-${hit.left}`,`${line.id}/segment-${hit.right}`],zones:zones.map(({id,chapterId,startT,endT})=>({id,chapterId,startT,endT})),splineSegments:[Math.floor(hit.tLeft*branch.path.segmentCount),Math.floor(hit.tRight*branch.path.segmentCount)],segmentCount:branch.path.segmentCount,visibleSegments,normalizedPoint:{x:hit.point.x/branch.width,y:hit.point.y/branch.height}};
    }));
  });
}
const results={};
const projections={};
for (const state of ['current','stage0','phase9']) {
  const root=state==='current'?repository:path.join(directory,state);
  const outfile=path.join(directory,`${state}.mjs`);
  await build({stdin:{contents:'export * from "@/lib/story/score/projection"; export * from "@/lib/story/score/composition";',resolveDir:root,loader:'ts'},alias:{'@':path.join(root,'src')},bundle:true,platform:'node',format:'esm',outfile,logLevel:'silent',nodePaths:[path.join(repository,'node_modules')],metafile:true}).then(async result=>writeFile(path.join(directory,`${state}-inputs.json`),JSON.stringify(result.metafile.inputs,null,2)+'\n'));
  const module=await import(pathToFileURL(outfile));
  results[state]={}; projections[state]={};
  for (const mode of modes) {
    const projection=module.buildStoryScoreProjection(mode);
    projections[state][mode]=projection;
    const occurrences=diagnose(projection);
    results[state][mode]={options:{viewportWidth:1440,viewportHeight:900},resolvedGeometryMode:projection.resolvedGeometryMode,width:projection.width,height:projection.height,oldEvidence:projection.evidence.pathSelfIntersections,oldStaffEvidence:projection.evidence.staffLineSelfIntersections,fingerprints:Object.fromEntries(Object.values(projection.branches).map(b=>[b.branch,module.storyScoreSemanticFingerprint(b.composition)])),occurrences};
    console.log(state,mode,occurrences.length);
  }
}
let id=0;
for(const mode of modes) {
  for(const occurrence of results.current[mode].occurrences) {
    occurrence.id=`ASM-SI-${String(++id).padStart(3,'0')}`;
    occurrence.comparison={};
    for(const baseline of ['stage0','phase9']) {
      const candidates=results[baseline][mode].occurrences.filter(b=>b.branch===occurrence.branch&&b.staffStep===occurrence.staffStep&&b.zones.some(z=>occurrence.zones.some(a=>a.chapterId===z.chapterId)));
      const closest=candidates.sort((a,b)=>Math.hypot(a.point.x-occurrence.point.x,a.point.y-occurrence.point.y)-Math.hypot(b.point.x-occurrence.point.x,b.point.y-occurrence.point.y))[0];
      const current=projections.current[mode].branches[occurrence.branch];
      const previous=projections[baseline][mode].branches[occurrence.branch];
      occurrence.comparison[baseline]={nearest:closest??null,pointDistance:closest?Math.hypot(closest.point.x-occurrence.point.x,closest.point.y-occurrence.point.y):null,fullStaffPointsByteEqual:JSON.stringify(current.model.staff.lines.map(l=>l.points))===JSON.stringify(previous.model.staff.lines.map(l=>l.points)),fullCenterSamplesByteEqual:JSON.stringify(Array.from({length:2049},(_,i)=>current.path.pointAt(i/2048)))===JSON.stringify(Array.from({length:2049},(_,i)=>previous.path.pointAt(i/2048)))};
    }
  }
}
await writeFile(path.join(directory,'diagnostics.json'),JSON.stringify(results,null,2)+'\n');
console.log('Saved',path.join(directory,'diagnostics.json'));

reproduction.localComparisonScript:
import {writeFile} from 'node:fs/promises';
import * as current from './current.mjs';
import * as previous from './stage0.mjs';
const now=current.buildStoryScoreProjection('horizontal-enhanced').branches.application;
const old=previous.buildStoryScoreProjection('horizontal-enhanced').branches.application;
const records=[];
// Compare the complete How arrival and Benefits entry, including cubic endpoints,
// derivative samples and all five analytic offset lines. Shift one spline index
// because the bounded Stage-1 Home cut removed one upstream knot.
for(let index=217;index<=234;index++) {
 let maximumPointDifference=0, maximumNormalDifference=0, maximumTangentDifference=0;
 for(let sample=0;sample<=64;sample++) {
  const a=(index+sample/64)/now.path.segmentCount;
  const b=(index+1+sample/64)/old.path.segmentCount;
  for(const method of ['pointAt','normalAt','tangentAt']) {
   const x=now.path[method](a),y=old.path[method](b);
   const difference=Math.hypot(x.x-y.x,x.y-y.y);
   if(method==='pointAt') maximumPointDifference=Math.max(maximumPointDifference,difference);
   if(method==='normalAt') maximumNormalDifference=Math.max(maximumNormalDifference,difference);
   if(method==='tangentAt') maximumTangentDifference=Math.max(maximumTangentDifference,difference);
  }
 }
 records.push({currentSplineSegment:index,baselineSplineSegment:index+1,maximumPointDifference,maximumNormalDifference,maximumTangentDifference});
}
await writeFile(new URL('./local-comparison.json',import.meta.url),JSON.stringify(records,null,2)+'\n');
console.log(records);
